// All settings for one experiment run. Change them here, then run the workflow.
// The Jev questions are also here, so you can tune them in one place.
const WINDOW_START = '2026-09-24T00:00:00Z'; // UTC, included
const WINDOW_END = '2026-10-01T00:00:00Z';   // UTC, not included
const MAX_COMMENTS = 250;                      // Use 25 for the first test run. One week is approx. 2,000.
const JEV_MODEL = 'jev-1.13.0';               // Pinned version. Do not use the alias while you tune thresholds.
const SECONDARY_THRESHOLD = 0.7;              // Topic Noul value that makes a secondary category
const PILLAR_THRESHOLD = 0.7;                 // Pillar Noul value that makes a pillar

// AXIS 1. One Choice picks the primary category.
const CATEGORY_CRITERIA = {
  'UX': {
    what: 'Interaction, flow, layout, visual design, navigation, editor behaviour, credential setup, save or undo, popups, wanting the product UI in another language. The product works but is awkward, confusing or pleasant. A vague opinion such as "not user friendly" or "convenient interface" is UX.',
    not_for: 'Errors, crashes or hangs (Reliability). Slowness (Performance).',
    examples: ['convenient interface', 'We dont have autosave!', 'the AI assistant builds most of my workflow now'],
  },
  'Reliability': {
    what: 'Failures, errors, crashes, blank pages, hangs, stuck loops, dropped connections, wrong results, bugs, difficult debugging. A vague opinion such as "buggy" or "unreliable" is Reliability.',
    not_for: 'A product that works but confuses (UX) or works but slowly (Performance).',
    examples: ['the page goes white and I need to refresh'],
  },
  'Performance': {
    what: 'Speed, latency, execution time. The product works correctly, just slowly. "too slow" is Performance.',
    not_for: 'Errors or hangs (Reliability).',
    examples: ['very flexible but too slow for free'],
  },
  'Pricing': {
    what: 'What n8n charges: cost, plan tiers, subscription value, trial length, credit or execution limits, discounts, value for money. A bare "expensive" is Pricing.',
    not_for: 'A cost point that exists because of self-hosting, such as "free when run locally" (Self-hosting/Deployment).',
    examples: ['expensive', 'simple and effective, although a bit expensive'],
  },
  'Integrations': {
    what: 'Availability, breadth, quality or absence of connectors and nodes for third-party services. Any comment that names an external service or connector.',
    not_for: 'Comments that name no external service or connector.',
    examples: ['good, but no claude code integrated', 'If there were more native connections I would have given it a 10.'],
  },
  'Documentation': {
    what: 'Quality, existence, coverage or translation of docs, help files, tutorials, the Academy, community learning content. "There is no doc for this". Missing doc translation.',
    not_for: 'The product itself being hard to learn (Learning Curve). Wanting the product UI in another language (UX).',
    examples: ['No foreign language (at least for doc or helpfile)'],
  },
  'Learning Curve': {
    what: 'The product itself is steep, complex, intense or intimidating. Not suitable for non-developers. Long time to competence. "I cannot figure this out".',
    not_for: 'Missing or poor docs (Documentation).',
    examples: ['its good but very intense. Would not recommend for non dev users.'],
  },
  'Self-hosting/Deployment': {
    what: 'Self-hosting, running locally, Docker, containers, community edition, open source and licensing, deployment platforms, install and setup effort, data on own infrastructure. Also a cost point that exists because of deployment.',
    not_for: 'Only what n8n charges (Pricing).',
    examples: ['I appreciate being able to run it fully locally in a dockerized container', 'to have it for free, I have to download so many things'],
  },
  'Support': {
    what: 'Interactions with the n8n support team or n8n staff.',
    not_for: 'Help from the community forum (Documentation).',
    examples: ['support never answered my ticket'],
  },
  'No Driver Named': {
    what: 'Carries a mood but names no product topic at all, or is unintelligible keyboard mash.',
    not_for: 'A vague opinion about a named topic. "expensive" names Pricing. "buggy" names Reliability.',
    examples: ['love it', 'muito bom, adorei', 'nothing', 'dfgdfg'],
  },
  'Other': {
    what: 'Clearly about a specific product topic that fits none of the other options, for example execution logs, roles or permissions.',
    not_for: 'Vague comments (No Driver Named).',
    examples: ['we need better execution logs and role permissions for our team'],
  },
};

// Secondary category. One Noul per topic category. Code picks the secondary.
const TOPICS = {
  topic_ux: ['UX', 'how the product is to use: interaction, flow, layout, visual design, navigation, editor behaviour, credential setup, save or undo, popups, ease of use'],
  topic_reliability: ['Reliability', 'failures, errors, crashes, blank pages, hangs, bugs, wrong results, difficult debugging'],
  topic_performance: ['Performance', 'speed, latency or execution time'],
  topic_pricing: ['Pricing', 'what n8n charges: cost, plans, trials, credit or execution limits, value for money'],
  topic_integrations: ['Integrations', 'connectors or nodes for third-party services, or a named external service'],
  topic_documentation: ['Documentation', 'docs, help files, tutorials, the Academy, learning content'],
  topic_learning_curve: ['Learning Curve', 'the product being steep, complex or not for non-developers'],
  topic_self_hosting: ['Self-hosting/Deployment', 'self-hosting, running locally, Docker, community edition, open source, install effort, own infrastructure'],
  topic_support: ['Support', 'the n8n support team or n8n staff'],
};

// AXIS 2. One Noul per pillar (code applies the "None unless clear" rule),
// and also one Choice, so the run can compare the two methods.
const PILLARS = {
  pillar_ai_building: ['AI Building',
    'The AI is authoring or fixing the automation: prompting to generate a workflow, the AI assistant or AI builder, generation quality, AI-assisted debugging, self-healing.',
    'AI that runs inside the workflow, or an external agent that drives n8n.'],
  pillar_visual_auditability: ['Visual Auditability',
    'Understanding one workflow: the canvas, data flow, node inputs and outputs, "I can see what happens", easier to follow than code, inspecting a run to understand it.',
    'Operating many workflows, or team control.'],
  pillar_runtime_governance: ['Runtime Governance',
    'Things that matter only with a team or many workflows: execution logs at scale, monitoring, alerting, roles, permissions, SSO, policy, audit trail, budget caps, environments, data-access control.',
    'Crashes, bugs, hangs and "does not work". These are never Runtime Governance.'],
  pillar_power_ceiling: ['Power & Ceiling',
    'Whether n8n can do the hard thing: Code node, HTTP request, webhooks, arbitrary code, Python or JavaScript, libraries, complex branching and loops, hitting a limit, needing more control over node internals.',
    'A passing adjective such as "flexible" or "powerful" when the comment is about something else.'],
  pillar_setup_activation: ['Setup & Activation',
    'The period before the user was productive: installing or running n8n, credentials, OAuth, API keys, connecting the first service, reaching a first working workflow, initial learning burden.',
    'The plain fact of running n8n yourself (Self-hosting & Openness).'],
  pillar_agents_vs_workflows: ['Agents vs Workflows',
    'The AI is a component inside the automation, or an external agent drives n8n: agents as a thing you build, agent tools, MCP, orchestration, deterministic versus probabilistic steps, human-in-the-loop.',
    'AI that authors the workflow (AI Building).'],
  pillar_self_hosting_openness: ['Self-hosting & Openness',
    'Sovereignty: self-hosting, running locally, Docker, community edition, open source and licensing, bring your own key, model choice, privacy, no lock-in, own infrastructure.',
    'The effort of installing or connecting (Setup & Activation).'],
  pillar_community_ecosystem: ['Community & Ecosystem',
    'Value made by other people: the community, the forum, third-party custom nodes, templates, creators, marketplace, external tools built on n8n.',
    '"community edition", which is a licensing tier. Docs and the Academy, which n8n makes.'],
};

const PILLAR_RULE = 'Price, cost, plans, trials and discounts are never a strategic bet. Documentation quality is never a strategic bet. A passing adjective is not enough: the bet must be what the comment is actually about.';

const questions = {
  category: {
    type: 'choice',
    instructions: {
      question: 'Which part of the n8n product is `comment` mainly about?',
      focus: 'Pick the one main topic area. A request does not decide the topic: "We dont have autosave!" is UX. When two options fit, pick the one that the most specific phrase in the comment belongs to.',
    },
    criteria: CATEGORY_CRITERIA,
  },
  pillar: {
    type: 'choice',
    instructions: {
      question: 'Which strategic bet is `comment` actually about?',
      focus: 'Most comments are None. Pick None when no bet is clearly addressed, or when two bets are equally plausible. ' + PILLAR_RULE,
    },
    criteria: Object.assign(
      Object.fromEntries(Object.values(PILLARS).map(([label, what, notFor]) => [label, { what, not_for: notFor }])),
      { 'None': 'No strategic bet is clearly addressed. Use this when in doubt.' },
    ),
  },
  sentiment: {
    type: 'choice',
    instructions: {
      question: 'What is the dominant tone of `comment` itself?',
      focus: 'Ignore `nps_score`. For "great, but X", pick the tone that dominates. Pick neutral only when the tone is truly balanced or absent.',
    },
    criteria: {
      positive: 'The dominant tone is approval.',
      negative: 'The dominant tone is dissatisfaction or complaint.',
      neutral: 'The tone is truly balanced, or there is no tone.',
    },
  },
  is_request: {
    type: 'noul',
    instructions: 'Does `comment` ask for, wish for, or imply wanting something that does not exist or does not work as wanted?',
    criteria: {
      true: 'For example "it would be great if", "please add", "there should be", "we dont have", "if there were more X I would give a 10".',
      false: 'The comment only describes what exists, gives praise, or reports a bug with no implied ask.',
    },
  },
  actionable: {
    type: 'noul',
    instructions: 'Could a product manager write a ticket title from `comment` without inventing any detail that the user did not give?',
    criteria: {
      true: 'The comment names a concrete, changeable specific: a named UI element, a described failure, a named third-party service, a named missing capability, a specific cost or limit, or a specific documentation gap.',
      false: 'The comment gives only an opinion, a mood, intensity, or a bare topic word such as "expensive", "too slow" or "not user friendly". Praise counts only when it names a specific mechanism.',
    },
  },
  is_english: {
    type: 'noul',
    instructions: 'Is `comment` written in English?',
  },
};

for (const [id, [label, definition]] of Object.entries(TOPICS)) {
  questions[id] = {
    type: 'noul',
    instructions: `Does \`comment\` contain a phrase that makes its own point about ${label}? ${label} means ${definition}.`,
    criteria: {
      true: `At least one phrase in the comment is about ${label}.`,
      false: `No phrase in the comment is about ${label}. A word that only describes a different point does not count.`,
    },
  };
}

for (const [id, [label, what, notFor]] of Object.entries(PILLARS)) {
  questions[id] = {
    type: 'noul',
    instructions: `Is \`comment\` actually about ${label}? ${label} means: ${what}`,
    criteria: {
      true: `The main point of the comment is about ${label}.`,
      false: `The comment is not about ${label}, or mentions it only in passing. Not ${label}: ${notFor} ${PILLAR_RULE}`,
    },
  };
}

return [{
  json: {
    window_start: WINDOW_START,
    window_end: WINDOW_END,
    max_comments: MAX_COMMENTS,
    jev_model: JEV_MODEL,
    secondary_threshold: SECONDARY_THRESHOLD,
    pillar_threshold: PILLAR_THRESHOLD,
    topic_labels: Object.fromEntries(Object.entries(TOPICS).map(([id, [label]]) => [id, label])),
    pillar_labels: Object.fromEntries(Object.entries(PILLARS).map(([id, [label]]) => [id, label])),
    jev_questions: questions,
  },
}];

// Copy of the filter rules in the live "Triage Feedback" node of "NPS daily swipe".
// Both models get the same comments that the live workflow sends to Sonnet.
// Change from the live node: the segmentation fields are not carried, because
// this experiment does not use them.
const LETTER = /\p{L}/u;
const LATIN_ONLY = /^[a-z0-9]+$/;

const GENERIC = new Set([
  'good', 'goood', 'goog', 'god', 'great', 'nice', 'top', 'best', 'cool',
  'love', 'wow', 'thx', 'ty', 'thanks', 'thank', 'perfect', 'amazing',
  'awesome', 'awsome', 'excellent', 'excelent', 'excelente', 'super',
  'superb', 'otimo', 'bom', 'bien', 'genial', 'fantastic', 'wonderful',
  'wonderfull', 'happy', 'mantap', 'bagus', 'verygood', 'gracias', 'danke',
  'merci', 'ok', 'okay', 'oke', 'yes', 'si', 'no', 'na', 'idk', 'fine',
  'hi', 'hello', 'test', 'teste', 'meh', 'because', 'cause', 'nothing',
  'muito', 'mucho', 'mucha', 'muchas', 'todas', 'yeah', 'like',
  'bad', 'poor', 'sad', 'terrible', 'awful', 'horrible',
]);

const MEANINGFUL_SHORT = new Set([
  'free', 'easy', 'slow', 'fast', 'cost', 'bug', 'bugs', 'lag', 'hard',
  'ux', 'ui', 'api', 'mcp', 'sql', 'csv', 'crm', 'http', 'ai', 'llm',
  'docs', 'doc', 'node', 'save', 'paid', 'n8n',
]);

const out = [];
const dropped = { noLetters: 0, repeatedChar: 0, generic: 0, shortToken: 0, tinyTokens: 0 };

for (const item of $input.all()) {
  const raw = (item.json.feedback ?? '').toString();
  const fb = raw.trim();

  if (!LETTER.test(fb)) { dropped.noLetters++; continue; }

  const norm = fb.toLowerCase().replace(/[^\p{L}\p{N}\p{M}\s]/gu, '').replace(/\s+/g, ' ').trim();
  const tokens = norm.split(' ').filter(Boolean);

  if (/^(.)\1+$/u.test(norm.replace(/\s/g, ''))) { dropped.repeatedChar++; continue; }

  if (tokens.length === 1 && GENERIC.has(tokens[0])) { dropped.generic++; continue; }

  if (tokens.length === 1 && LATIN_ONLY.test(tokens[0]) && tokens[0].length <= 4 && !MEANINGFUL_SHORT.has(tokens[0])) {
    dropped.shortToken++;
    continue;
  }

  if (tokens.length > 1 && tokens.every(t => LATIN_ONLY.test(t) && t.length <= 2)) {
    dropped.tinyTokens++;
    continue;
  }

  out.push({ json: {
    feedback: raw,
    nps: item.json.nps,
    response_timestamp: item.json.timestamp ?? null,
  } });
}

const totalDropped = Object.values(dropped).reduce((a, b) => a + b, 0);
console.log(`[Triage] in=${$input.all().length} dropped=${totalDropped} ${JSON.stringify(dropped)} toClassify=${out.length}`);

return out;

// One Jev request for each comment. The fixed questions are in "Experiment config".
// This node adds only the parts that change for each comment: the state, and
// the evidence question. Jev cannot write text, so it cannot quote evidence.
// Instead, code splits the comment into clauses and Jev picks one clause.
// The evidence is then always verbatim, but at clause level.
const NONE = 'none of these';
const MAX_CLAUSES = 30;
const MAX_CLAUSE_CHARS = 300;

function clauses(text) {
  const out = [];
  for (const line of String(text).split(/\n+/)) {
    const parts = line.split(/(?<=[.!?;:])\s+|\s*,\s*|\s+[-–]\s+|\s+(?=(?:but|however|although|though|except|mas|pero|aber|mais)\s)/i);
    for (const part of parts) {
      const clause = part.trim().replace(/^[\s"'“”(]+|[\s"'“”).!?;:,]+$/g, '').slice(0, MAX_CLAUSE_CHARS);
      if (/\p{L}/u.test(clause) && clause !== NONE && !out.includes(clause)) out.push(clause);
    }
  }
  return out.slice(0, MAX_CLAUSES);
}

return $input.all().map(item => {
  const comment = String(item.json.feedback ?? '').trim();
  const found = clauses(comment);
  const options = found.length > 0 ? found : [comment.slice(0, MAX_CLAUSE_CHARS)];

  const criteria = {};
  for (const option of options) criteria[option] = null;
  criteria[NONE] = 'No part of the comment names a concrete, changeable specific. The comment gives only an opinion, a mood, intensity, or a bare topic word such as "expensive", "too slow" or "not user friendly".';

  return { json: {
    ...item.json,
    jev_state: { comment, nps_score: item.json.nps },
    jev_evidence_question: {
      type: 'choice',
      instructions: {
        question: 'Which part of `comment` names a concrete, changeable specific?',
        focus: 'A concrete, changeable specific is a named UI element, a described failure, a named third-party service, a named missing capability, a specific cost or limit, or a specific documentation gap.',
      },
      criteria,
    },
  } };
});

// Turns the Jev answers into the same fields as the Sonnet arm, with the same
// rules as the live Zip node: enum clamps, secondary is not the primary, max two
// categories, No Driver Named means pillar None, actionable means evidence is not empty.
// It also keeps the raw probabilities, so the analysis can test other thresholds.
// "Ask Jev" returns only the API response, so the comment fields come from
// "Build Jev Request" (same item order).
const requests = $('Build Jev Request').all();
const config = $('Experiment config').first().json;
const TOPIC_LABELS = config.topic_labels;
const PILLAR_LABELS = config.pillar_labels;
const SECONDARY_T = config.secondary_threshold;
const PILLAR_T = config.pillar_threshold;
const ALT_SECONDARY_T = 0.3;
const NONE = 'none of these';

const ALLOWED_CATEGORIES = ['UX', 'Reliability', 'Performance', 'Pricing', 'Integrations', 'Documentation', 'Learning Curve', 'Self-hosting/Deployment', 'Support', 'No Driver Named', 'Other'];
const ALLOWED_SENTIMENT = ['positive', 'negative', 'neutral'];
const ALLOWED_PILLARS = ['AI Building', 'Visual Auditability', 'Runtime Governance', 'Power & Ceiling', 'Setup & Activation', 'Agents vs Workflows', 'Self-hosting & Openness', 'Community & Ecosystem', 'None'];

const round = (n) => Math.round((Number(n) || 0) * 1000) / 1000;
const roundMap = (m) => Object.fromEntries(Object.entries(m || {}).map(([k, v]) => [k, round(v)]));

return $input.all().map((item, i) => {
  const { answers, model, usage, error } = item.json;
  const base = requests[item.pairedItem?.item ?? i]?.json ?? {};
  const { jev_state, jev_evidence_question, ...rest } = base;

  if (error || !answers) {
    const message = typeof error === 'string' ? error : (error?.message || (error ? JSON.stringify(error) : 'no answers'));
    return { json: {
      ...rest,
      jev_status: `error: ${message}`,
      jev_category: '', jev_category_secondary: '', jev_category_secondary_alt: '',
      jev_evidence: '', jev_is_request: false, jev_actionable: false, jev_actionable_noul: false,
      jev_sentiment: '', jev_pillar_noul: '', jev_pillar_choice: '',
      jev_category_confidence: null, jev_is_english: null,
      jev_input_tokens: 0, jev_model: model ?? '',
    } };
  }

  let status = 'ok';
  let category = answers.category?.choice;
  if (!ALLOWED_CATEGORIES.includes(category)) { status = `enum_violation(${category})`; category = 'Other'; }
  const isNoDriver = category === 'No Driver Named';

  // Secondary, method 1: the highest topic Noul above the threshold that is not the primary.
  const topicNouls = Object.fromEntries(Object.entries(TOPIC_LABELS).map(([id, label]) => [label, answers[id]?.noul ?? 0]));
  const secondaryCandidates = Object.entries(topicNouls)
    .filter(([label, p]) => label !== category && p >= SECONDARY_T)
    .sort((a, b) => b[1] - a[1]);
  const secondary = isNoDriver ? '' : (secondaryCandidates[0]?.[0] ?? '');

  // Secondary, method 2: the second-highest option of the category Choice.
  const categoryProbs = answers.category?.probabilities ?? {};
  const ranked = Object.entries(categoryProbs).sort((a, b) => b[1] - a[1]);
  const second = ranked[1];
  const secondaryAlt = (!isNoDriver && second && second[1] >= ALT_SECONDARY_T && !['No Driver Named', 'Other'].includes(second[0])) ? second[0] : '';

  // Pillar, method 1: one pillar Noul is above the threshold and no other one is (tie-break 10).
  const pillarNouls = Object.fromEntries(Object.entries(PILLAR_LABELS).map(([id, label]) => [label, answers[id]?.noul ?? 0]));
  const pillarRanked = Object.entries(pillarNouls).sort((a, b) => b[1] - a[1]);
  let pillarNoul = (pillarRanked[0]?.[1] >= PILLAR_T && !(pillarRanked[1]?.[1] >= PILLAR_T)) ? pillarRanked[0][0] : 'None';

  // Pillar, method 2: the pillar Choice.
  let pillarChoice = ALLOWED_PILLARS.includes(answers.pillar?.choice) ? answers.pillar.choice : 'None';

  if (isNoDriver) { pillarNoul = 'None'; pillarChoice = 'None'; }

  const sentiment = ALLOWED_SENTIMENT.includes(answers.sentiment?.choice) ? answers.sentiment.choice : 'neutral';
  const evidenceChoice = answers.evidence?.choice;
  const evidence = (!evidenceChoice || evidenceChoice === NONE) ? '' : evidenceChoice;

  return { json: {
    ...rest,
    jev_status: status,
    jev_category: category,
    jev_category_secondary: secondary,
    jev_category_secondary_alt: secondaryAlt,
    jev_evidence: evidence,
    jev_is_request: (answers.is_request?.noul ?? 0) >= 0.5,
    jev_actionable: evidence.length > 0,
    jev_actionable_noul: (answers.actionable?.noul ?? 0) >= 0.5,
    jev_sentiment: sentiment,
    jev_pillar_noul: pillarNoul,
    jev_pillar_choice: pillarChoice,
    jev_category_confidence: round(answers.category?.confidence),
    jev_is_english: round(answers.is_english?.noul),
    jev_input_tokens: usage?.input_tokens ?? 0,
    jev_model: model ?? '',
    jev_raw: {
      category_probs: roundMap(categoryProbs),
      topic_nouls: roundMap(topicNouls),
      pillar_nouls: roundMap(pillarNouls),
      pillar_choice_probs: roundMap(answers.pillar?.probabilities),
      evidence_confidence: round(answers.evidence?.confidence),
      is_request: round(answers.is_request?.noul),
      actionable: round(answers.actionable?.noul),
    },
  } };
});

// One row for each comment, with the Sonnet result, the Jev result and agree flags.
// Agreement is not accuracy. The rows where the models disagree are the rows to adjudicate.
const norm = (s) => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, '').replace(/\s+/g, ' ').trim();

function evidenceAgrees(a, b) {
  const x = norm(a);
  const y = norm(b);
  if (!x && !y) return true;
  if (!x || !y) return false;
  return x.includes(y) || y.includes(x);
}

function sameSet(a1, a2, b1, b2) {
  const a = [a1, a2].filter(Boolean).sort().join('|');
  const b = [b1, b2].filter(Boolean).sort().join('|');
  return a === b;
}

return $input.all().map(({ json: r }) => {
  const agree = {
    category: r.sonnet_category === r.jev_category,
    category_set: sameSet(r.sonnet_category, r.sonnet_category_secondary, r.jev_category, r.jev_category_secondary),
    category_set_alt: sameSet(r.sonnet_category, r.sonnet_category_secondary, r.jev_category, r.jev_category_secondary_alt),
    secondary: r.sonnet_category_secondary === r.jev_category_secondary,
    secondary_alt: r.sonnet_category_secondary === r.jev_category_secondary_alt,
    pillar_noul: r.sonnet_strategy_pillar === r.jev_pillar_noul,
    pillar_choice: r.sonnet_strategy_pillar === r.jev_pillar_choice,
    sentiment: r.sonnet_sentiment === r.jev_sentiment,
    is_request: r.sonnet_is_request === r.jev_is_request,
    actionable: r.sonnet_actionable === r.jev_actionable,
    actionable_noul: r.sonnet_actionable === r.jev_actionable_noul,
    evidence: evidenceAgrees(r.sonnet_evidence, r.jev_evidence),
  };
  const mainFields = ['category', 'secondary', 'pillar_noul', 'sentiment', 'is_request', 'actionable'];
  return { json: {
    ...r,
    agree,
    disagreements: mainFields.filter(f => !agree[f]),
  } };
});

// One summary item for the run. Sonnet tokens and the time of each model are
// not visible to a Code node. Read them from the execution data of
// "Anthropic Chat Model", "Classify Batch (Sonnet)" and "Ask Jev".
const JEV_PRICE_PER_MTOK = 0.042;
const allRows = $input.all().map(i => i.json);
// Agreement uses only rows where both models returned a result.
const rows = allRows.filter(r => r.sonnet_status !== 'unmatched' && !String(r.jev_status).startsWith('error'));
const n = rows.length;
const pct = (count, total) => total ? Math.round((count / total) * 1000) / 10 : null;

const agreeKeys = rows.length ? Object.keys(rows[0].agree) : [];
const agreement = Object.fromEntries(agreeKeys.map(k => [k, pct(rows.filter(r => r.agree[k]).length, n)]));

function countBy(field) {
  const out = {};
  for (const r of rows) out[r[field] || '(empty)'] = (out[r[field] || '(empty)'] || 0) + 1;
  return Object.fromEntries(Object.entries(out).sort((a, b) => b[1] - a[1]));
}

function categoryAgreement(subset) {
  return { n: subset.length, category_agree_pct: pct(subset.filter(r => r.agree.category).length, subset.length) };
}

const english = rows.filter(r => (r.jev_is_english ?? 0) >= 0.5);
const notEnglish = rows.filter(r => r.jev_is_english !== null && (r.jev_is_english ?? 0) < 0.5);

const byConfidence = {
  'confidence >= 0.8': categoryAgreement(rows.filter(r => r.jev_category_confidence >= 0.8)),
  '0.5 to 0.8': categoryAgreement(rows.filter(r => r.jev_category_confidence >= 0.5 && r.jev_category_confidence < 0.8)),
  'below 0.5': categoryAgreement(rows.filter(r => r.jev_category_confidence !== null && r.jev_category_confidence < 0.5)),
};

const jevTokens = allRows.reduce((sum, r) => sum + (r.jev_input_tokens || 0), 0);

return [{ json: {
  comments: allRows.length,
  comments_scored: n,
  sonnet_unmatched: allRows.filter(r => r.sonnet_status === 'unmatched').length,
  sonnet_enum_violations: allRows.filter(r => String(r.sonnet_status).startsWith('enum_violation')).length,
  jev_errors: allRows.filter(r => String(r.jev_status).startsWith('error')).length,
  jev_enum_violations: allRows.filter(r => String(r.jev_status).startsWith('enum_violation')).length,
  agreement_pct: agreement,
  category_agreement_by_language: { english: categoryAgreement(english), not_english: categoryAgreement(notEnglish) },
  category_agreement_by_jev_confidence: byConfidence,
  rows_with_any_disagreement: rows.filter(r => r.disagreements.length > 0).length,
  distribution: {
    sonnet_category: countBy('sonnet_category'),
    jev_category: countBy('jev_category'),
    sonnet_pillar: countBy('sonnet_strategy_pillar'),
    jev_pillar_noul: countBy('jev_pillar_noul'),
    jev_pillar_choice: countBy('jev_pillar_choice'),
  },
  jev_input_tokens_total: jevTokens,
  jev_input_tokens_per_comment: allRows.length ? Math.round(jevTokens / allRows.length) : 0,
  jev_cost_usd_estimate: Math.round(jevTokens / 1e6 * JEV_PRICE_PER_MTOK * 1e6) / 1e6,
  jev_model: allRows.find(r => r.jev_model)?.jev_model ?? '',
} }];

const items = $input.all().map(i => i.json);
const lines = items.map((it, idx) => `${idx}. NPS=${it.nps} | ${(it.feedback || '').replace(/\n/g, ' ')}`).join('\n');
return [{ json: { items, promptText: lines } }];

// Same enum clamps as the live "Zip Batch Results" node, and the same derived
// actionable (true when evidence is not empty). Changes from the live node:
// it keeps exp_id and evidence_secondary, and it writes every field with a
// sonnet_ prefix so that the Jev fields can sit next to them.
const original = $('Build Sonnet Batch Prompt').first().json.items;
const classifications = $json.output || [];

const ALLOWED_CATEGORIES = ['UX', 'Reliability', 'Performance', 'Pricing', 'Integrations', 'Documentation', 'Learning Curve', 'Self-hosting/Deployment', 'Support', 'No Driver Named', 'Other'];
const ALLOWED_SENTIMENT = ['positive', 'negative', 'neutral'];
const ALLOWED_PILLARS = ['AI Building', 'Visual Auditability', 'Runtime Governance', 'Power & Ceiling', 'Setup & Activation', 'Agents vs Workflows', 'Self-hosting & Openness', 'Community & Ecosystem', 'None'];

const byIndex = {};
for (const c of classifications) {
  if (c && c.index !== undefined && c.index !== null) byIndex[Number(c.index)] = c;
}

return original.map((item, idx) => {
  const c = byIndex[idx];

  if (!c) {
    return { json: {
      ...item,
      sonnet_status: 'unmatched',
      sonnet_category: 'Other', sonnet_category_secondary: '',
      sonnet_evidence: '', sonnet_evidence_secondary: '',
      sonnet_is_request: false, sonnet_actionable: false,
      sonnet_sentiment: 'neutral', sonnet_strategy_pillar: 'None',
    } };
  }

  const evidence = typeof c.evidence === 'string' ? c.evidence.trim() : '';
  let status = 'ok';
  let category = c.category;
  if (!ALLOWED_CATEGORIES.includes(category)) {
    status = `enum_violation(${category})`;
    category = 'Other';
  }
  let categorySecondary = ALLOWED_CATEGORIES.includes(c.category_secondary) ? c.category_secondary : '';
  if (categorySecondary === category) categorySecondary = '';
  const sentiment = ALLOWED_SENTIMENT.includes(c.sentiment) ? c.sentiment : 'neutral';
  let pillar = ALLOWED_PILLARS.includes(c.strategy_pillar) ? c.strategy_pillar : 'None';
  if (category === 'No Driver Named') pillar = 'None';

  return { json: {
    ...item,
    sonnet_status: status,
    sonnet_category: category,
    sonnet_category_secondary: categorySecondary,
    sonnet_evidence: evidence,
    sonnet_evidence_secondary: typeof c.evidence_secondary === 'string' ? c.evidence_secondary.trim() : '',
    sonnet_is_request: c.is_request === true,
    sonnet_actionable: evidence.length > 0,
    sonnet_sentiment: sentiment,
    sonnet_strategy_pillar: pillar,
  } };
});
